const text = ($json.message.text || '').trim();
return [{ json: { chat_id: chatId, text_raw: text, first_name: $json.message.chat.first_name || '', username: $json.message.chat.username || '' } }];

const ahora = new Date();
const tutores = $('Sheets - Tutores para Recordatorio').all().map(i => i.json);
const tutorias = $('Sheets - Obtener Tutorías Próximas').all().map(i => i.json);
const proximas = tutorias.filter(t => {
  if (String(t.estado || '').toUpperCase() !== 'CONFIRMADA') return false;
  const fecha = new Date(t.fecha_hora);
  if (isNaN(fecha.getTime())) return false;
  const diffMin = (fecha - ahora) / 60000;
  return diffMin > 0 && diffMin <= 60;
});
return proximas.map(t => {
  const tut = tutores.find(x => String(x.id_tutor) === String(t.id_tutor)) || {};
  return { json: {
    telegram_user: t.telegram_user,
    email_tutor: tut.email_tutor || '',
    materia: t.materia,
    fecha_hora: t.fecha_hora,
  } };
});

